import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

/** The content root, so a watcher event can be turned into a collection-relative slug. */
const CONTENT_DIR = join(dirname(dirname(fileURLToPath(import.meta.url))), 'src', 'content', 'docs');

/**
 * Warns when a remark or rehype plugin changes, because the dev server will not pick it up.
 *
 * Almost everything on a reference page is generated by the plugins in `src/plugins/`, and editing one
 * leaves the dev server serving the previous HTML for all 70 pages. Astro's content-layer cache is keyed on
 * each content file's digest, and plugin code is not part of that key, so nothing about the edit invalidates
 * it.
 *
 * **A restart alone does not fix it.** The store is on disk at `.astro/data-store.json` — Astro's default
 * `cacheDir` is `./.astro`, not `node_modules/.astro` — so a fresh process reads the same stale render back.
 * The sequence that works:
 *
 *     npx astro dev stop && rm -f .astro/data-store.json && npx astro dev --background
 *
 * `npm run dev` passes `--force`, which does the same thing, but the background daemon wrapper launches
 * `astro dev --json` and drops the flag — so `npm run dev -- --background` looks like it should work and does
 * not. Deleting the store is the reliable move. Stop the server first: deleting it from under a running
 * server leaves it listening while it answers 404 for every route.
 *
 * This file does not try to fix that, because both attempts at fixing it were worse than the warning:
 *
 *   1. Deleting the cache directories from a Vite watcher hook. Destroys the content store from under
 *      the running server, which then keeps listening while answering 404 for every route — including
 *      the home page — and `astro dev status` loses the process, so the next `npm run dev` takes a
 *      different port while the broken one keeps the old one. Every page 404s and nothing says why.
 *      Deleting the store by hand between a `stop` and a start is the same operation done safely.
 *   2. Astro's `refreshContent` hook. Safe, and it does re-run the loaders — but re-running them
 *      re-renders with the plugin module already in memory, so the output does not change. Verified by
 *      putting a marker in a plugin and watching the served HTML not move.
 *
 * So the useful thing left to do is say so, loudly, at the moment it happens. A visible instruction
 * beats a silent stale page, which is what cost an hour of chasing a header that was rendering
 * correctly in the build the whole time.
 *
 * **The same store also caches a render that FAILED, and this warning does not fire for it.** A page
 * whose plugins threw is stored with its front matter and an empty body, so it serves a correct `<h1>`
 * — Starlight builds that from `title` — inside an empty `.cs-prose`, forever, with nothing in the log
 * after the original error scrolls away. Fixing the plugin does not help: no content file changed, so
 * nothing re-renders, and a probe added to a plugin never even runs. Touching the `.md` does not help
 * either.
 *
 * The signature is worth knowing because it looks like a plugin bug and is not: **an empty
 * `.cs-prose` with a correct `<h1>`, in dev, while the production build renders the page fine.** The
 * remedy is the same store deletion above. Seen on `/components` — the store was written seconds
 * before the fix to `remark-component-api.js` landed, and served an empty browse page from then on.
 *
 * **A third case, which this file now warns about: adding or deleting a page staler its directory's
 * index.** `remark-page-index` builds a listing by reading the directory, and that read is not part of
 * the index page's digest — so creating a sibling changes what the listing *should* say while nothing
 * invalidates what it already said. The index keeps serving the old list indefinitely.
 *
 * It is worth calling out separately because it mimics a bug in the wrong place, and it wastes the
 * obvious diagnosis. Seen on `/frameworks` after two pages were added: the page's *prose* had updated
 * in the same session, which is exactly the evidence that says "the cache is fine, the plugin is
 * broken" — and it was the opposite. The prose had updated because that edit changed the page's own
 * digest; the two new files, added minutes later, changed nothing about it. `touch` does not help
 * either, since the digest is over content and not mtime.
 *
 * So the fix is to change the index page's content — any real change will do — or to delete the store
 * as above. The warning names the page that went stale, because knowing *which* index to poke is the
 * part that is otherwise guesswork.
 *
 * **A fourth case, which nothing here can warn about: the watcher itself dies.** The three above all share
 * a shape — the content digest does not change, so nothing invalidates. This one is the opposite. Editing a
 * page changes its digest and *still* nothing happens, because the server has stopped reacting to content
 * events at all.
 *
 * Seen after ~4 hours of uptime: `.astro/data-store.json` carried the mtime of server startup and had not
 * been rewritten since, while four hours of markdown edits sat unserved. Edits to `.astro` and `.js` files
 * kept working throughout, which is what makes it so misleading — the server is plainly alive and plainly
 * recompiling, just not for content. Confirmed by appending a marker to a `.md`, waiting, and seeing
 * neither a re-render nor a store write.
 *
 * The diagnosis is two commands, and worth reaching for before suspecting a plugin:
 *
 *     ls -lT .astro/data-store.json          # if this is the server's start time, the watcher is dead
 *     curl -s localhost:4321/<page>/ | grep <something you just typed>
 *
 * The remedy is the same stop / delete / start above. **Editing the page does not help** — which is the
 * trap, because that is exactly the advice the third case gives, and following it here just produces more
 * unserved edits and more confidence that the bug is somewhere else.
 */
export function pluginWatcher() {
  const isPluginFile = (path) => /src[/\\](plugins[/\\]|component-categories\.js$|theme-sync\.js$)/.test(path);

  /**
   * Every page whose body is a listing of `dir`, so a warning can name it.
   *
   * `pageIndex: true` lists the directory the page sits in; `pageIndex: <dir>` lists that one from
   * outside it. Read fresh each time rather than cached, since the answer changes as pages are added.
   */
  const indexesListing = (dir) => {
    const pages = [];

    const walk = (relative) => {
      for (const entry of readdirSync(join(CONTENT_DIR, relative), {
        withFileTypes: true,
      })) {
        const next = relative ? `${relative}/${entry.name}` : entry.name;

        if (entry.isDirectory()) {
          walk(next);
          continue;
        }

        if (!entry.name.endsWith('.md')) {
          continue;
        }

        // Only the front matter matters, and it is always at the top, so this does not need a parser.
        const head = readFileSync(join(CONTENT_DIR, next), 'utf-8').slice(0, 600);
        const match = /^pageIndex: *(.+)$/m.exec(head);

        if (!match) {
          continue;
        }

        const value = match[1].trim();
        const listed = value === 'true' ? next.split('/').slice(0, -1).join('/') : value;

        if (listed === dir) {
          pages.push(next);
        }
      }
    };

    walk('');

    return pages;
  };

  return {
    name: 'cornerstone-docs:plugin-watcher',
    hooks: {
      'astro:server:setup': ({ server, logger }) => {
        server.watcher.on('change', (path) => {
          if (isPluginFile(path)) {
            logger.warn(`${path.split('/').pop()} changed. A plugin edit does not invalidate the content cache,`);
            logger.warn('and a restart on its own reads the same stale render back out of .astro/data-store.json.');
            logger.warn('Run: npx astro dev stop && rm -f .astro/data-store.json && npx astro dev --background');
          }
        });

        // Adding or deleting a page silently staler its directory's index — the third case above.
        for (const event of ['add', 'unlink']) {
          server.watcher.on(event, (path) => {
            if (!path.startsWith(CONTENT_DIR) || !path.endsWith('.md')) {
              return;
            }

            const dir = dirname(relative(CONTENT_DIR, path)).replace(/\\/g, '/');
            const affected = indexesListing(dir === '.' ? '' : dir);

            if (!affected.length) {
              return;
            }

            const verb = event === 'add' ? 'added' : 'deleted';

            logger.warn(`${relative(CONTENT_DIR, path)} was ${verb}, so ${affected.join(', ')} is now stale.`);
            logger.warn("A listing is built by reading the directory, which is not part of the index page's");
            logger.warn('own digest — so nothing re-renders it. Edit that page, or delete the store:');
            logger.warn('npx astro dev stop && rm -f .astro/data-store.json && npx astro dev --background');
          });
        }
      },
    },
  };
}
